export function InfoState({
  title = "{{title}}",
  message = "{{message}}",
  icon = "{{icon}}",
  dismissible = {{dismissible}},
}) {
  const glyph = { info: "i", tip: "★", note: "✎" }[icon] ?? "i";
  return (
    <div role="status" aria-live="polite" style={{ display: "flex", alignItems: "flex-start", gap: 10, maxWidth: 380,
      padding: "12px 14px", borderRadius: 10, background: "color-mix(in srgb, #BFD9F2 35%, #FAF7F2)",
      boxSizing: "border-box", font: "13.5px/1.45 system-ui, sans-serif", color: "#241430" }}>
      <span aria-hidden="true" style={{ width: 20, height: 20, borderRadius: "50%", flexShrink: 0, background: "#2F6FA8",
        color: "#FAF7F2", display: "grid", placeItems: "center", fontSize: 11, fontWeight: 700 }}>{glyph}</span>
      <div style={{ flex: 1 }}>
        <p style={{ margin: "0 0 2px", fontWeight: 700 }}>{title}</p>
        <p style={{ margin: 0, color: "#241430b3" }}>{message}</p>
      </div>
      {dismissible && (
        <button type="button" aria-label={`Dismiss ${title}`} style={{ border: "none", background: "transparent",
          fontSize: 15, cursor: "pointer", color: "#241430", padding: 2 }}>×</button>
      )}
    </div>
  );
}
